  "@graph": [
    {
      "@type": "Article",
      "headline": "Vad är zeaxantin — och vad säger forskningen om immunförsvar?",
      "description": "Zeaxantin är ett karotenoid känt för ögonhälsa. Ny forskning från University of Chicago visar att det också kan påverka immunförsvarets T-celler. Vi undersöker vad evidensen faktiskt säger.",
      "datePublished": "2026-06-14",
      "dateModified": "2026-06-14",
      "author": { "@type": "Person", "name": "Jarmo Halonen" },
      "publisher": { "@type": "Organization", "name": "LevNytt", "url": "https://levnytt.se" },
